7	 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	#include "send_state.h"
12	
13	#include "common/llm_log.h"
14	#include "common/llm_utils.h"
15	#include "common/mem_utils.h"
16	#include "data_transfer/d2h_data_transfer_job.h"
17	#include "data_transfer/h2d_data_transfer_job.h"
18	#include "data_transfer/d2d_data_transfer_job.h"
19	#include "common/llm_checker.h"
20	#include "common/llm_scope_guard.h"
21	#include "common/transfer_message_limits.h"
22	
23	namespace llm {
24	namespace {
25	constexpr int32_t kTransferTypeD2D = 0;
26	constexpr int32_t kTransferTypeD2H = 1;
27	constexpr int32_t kTransferTypeH2D = 2;
28	constexpr int32_t kDefaultTimeoutInMs = 1800 * 1000;  // 1800s
29	
30	ge::Status ValidateBufferInfoLens(const TransferCacheReq &request, uint32_t buffer_info_multiplier) {
31	  using namespace transfer_message_limits;
32	  if (request.buffer_info_count == 0U) {
33	    return ge::SUCCESS;
34	  }
35	  for (uint32_t i = 0U; i < request.buffer_info_count; ++i) {
36	    const auto &src_buffer_info = request.transfer_infos[request.dst_addr_count + i].buffer_info;
37	    LLM_CHK_BOOL_RET_STATUS(src_buffer_info.buffer_len > 0U, ge::LLM_PARAM_INVALID,
38	                            "src buffer_info[%u].buffer_len is 0", i);
39	    if (buffer_info_multiplier > kBufferInfoMultiplierD2h) {
40	      const auto &dst_buffer_info =
41	          request.transfer_infos[request.dst_addr_count + request.buffer_info_count + i].buffer_info;
42	      LLM_CHK_BOOL_RET_STATUS(dst_buffer_info.buffer_len > 0U, ge::LLM_PARAM_INVALID,
43	                              "dst buffer_info[%u].buffer_len is 0", i);
44	    }
45	  }
46	  return ge::SUCCESS;
47	}
48	
49	ge::Status ValidateTransferRequest(const TransferCacheReq &request, int32_t transfer_type) {
50	  using namespace transfer_message_limits;
51	  LLM_CHK_BOOL_RET_STATUS(request.dst_addr_count > 0U, ge::LLM_PARAM_INVALID, "dst_addr_count is 0");
52	  LLM_CHK_BOOL_RET_STATUS(request.dst_addr_count <= kMaxDstAddrCount, ge::LLM_PARAM_INVALID,
53	                          "dst_addr_count:%u exceeds max:%u", request.dst_addr_count, kMaxDstAddrCount);
54	
55	  const uint32_t buffer_info_multiplier =
56	      (transfer_type == kTransferTypeD2H) ? kBufferInfoMultiplierD2h : kBufferInfoMultiplierD2dH2d;
57	  const uint64_t transfer_info_count = static_cast<uint64_t>(request.dst_addr_count) +
58	                                       static_cast<uint64_t>(request.buffer_info_count) * buffer_info_multiplier;
59	  LLM_CHK_BOOL_RET_STATUS(transfer_info_count <= kMaxTransferInfoCount, ge::LLM_PARAM_INVALID,
60	                          "transfer info count:%lu exceeds max:%lu, dst_addr_count:%u, buffer_info_count:%u",
61	                          transfer_info_count, kMaxTransferInfoCount, request.dst_addr_count,
62	                          request.buffer_info_count);
63	
64	  // req_size is intentionally NOT compared for equality here, to stay compatible with legacy peers (older D2D/H2D
65	  // clients do not populate req_size, so a strict check would reject otherwise-valid cross-version requests). Memory
66	  // safety does not rely on req_size: the dst_addr_count / transfer_info_count bounds above keep every transfer_infos[]
67	  // access inside the fixed request buffer, and the server-side D2H recv-flag base is derived from these validated
68	  // counts (see D2HDataTransferJob::Initialize) rather than the wire req_size, so a forged req_size cannot redirect
69	  // remote writes.
70	  LLM_CHK_STATUS_RET(ValidateBufferInfoLens(request, buffer_info_multiplier), "Failed to validate buffer info lens");
71	  return ge::SUCCESS;
72	}
73	}  // namespace
74	ge::Status SendState::Preprocess(CommEntity &entity) {
75	  auto ret = Prepare(entity);
76	  if (ret != ge::SUCCESS) {
77	    LLM_CHK_STATUS_RET(entity.SendResponse(ret));
78	    return Postprocess(entity);
79	  }
80	  return Process(entity);
81	}
82	
83	ge::Status SendState::Prepare(CommEntity &entity) {
84	  auto timeout_in_ms = kDefaultTimeoutInMs;
85	  auto &request = entity.GetRequest();
86	  if (request.timeout_in_ms > 0) {
87	    timeout_in_ms = request.timeout_in_ms;
88	    LLMLOGI("set timeout by request = %d(ms)", timeout_in_ms);
89	  }
90	  entity.SetTimeoutPoint(std::chrono::steady_clock::now() + std::chrono::milliseconds(timeout_in_ms));
91	  CacheEntry cache_entry{};
92	  uint64_t offset;
93	  LLM_CHK_STATUS_RET(QueryCacheEntryAndOffset(entity, cache_entry, offset));
94	  LLMLOGI("Query cache entry success, offset = %lu", offset);
95	  LLM_CHK_STATUS_RET(CheckParam(cache_entry, request), "Failed to check param");
96	  auto transfer_type = ResolveTransferType(entity.GetRequest(), cache_entry);
97	  LLMLOGI("transfer type = %d", transfer_type);
98	  LLM_CHK_BOOL_RET_STATUS(transfer_type >= 0, ge::LLM_FEATURE_NOT_ENABLED,
99	                          "dst_placement = %d, src_placement = %d is not supported", entity.GetRequest().dst_placement,
100	                          static_cast<int32_t>(cache_entry.placement));
101	  LLM_CHK_STATUS_RET(ValidateTransferRequest(request, transfer_type), "Failed to validate transfer request");
102	  if (transfer_type == kTransferTypeD2H) {
103	    entity.SetDataTransferJob(MakeUnique<D2HDataTransferJob>());
104	  } else if (transfer_type == kTransferTypeH2D) {
105	    entity.SetDataTransferJob(MakeUnique<H2DDataTransferJob>());
106	  } else {  // D2D
107	    entity.SetDataTransferJob(MakeUnique<D2DDataTransferJob>());
108	  }
109	  const auto &transfer_job = entity.GetDataTransferJob();
110	  LLM_CHECK_NOTNULL(transfer_job);
111	  LLM_CHK_STATUS_RET(transfer_job->Initialize(cache_entry, entity, offset));
112	  return ge::SUCCESS;
113	}
114	
115	ge::Status SendState::Process(CommEntity &entity) {
116	  if (std::chrono::steady_clock::now() > entity.GetTimeoutPoint()) {
117	    entity.SendResponse(ge::LLM_TIMEOUT);
118	    LLMLOGE(ge::FAILED, "handle request timeout");
119	    return Postprocess(entity);
120	  }
121	  bool is_done = false;
122	  LLM_CHK_STATUS_RET(entity.GetDataTransferJob()->Process(is_done));
123	  if (is_done) {
124	    const auto &data_cache_key = entity.GetCacheKeyToRemove();
125	    if (data_cache_key.first != UINT64_MAX) {
126	      LLM_CHK_STATUS(entity.GetCacheManager()->RemoveCacheKey(data_cache_key, false,
127	                                                              GetLayerRangeTensorIndices(entity.GetRequest())));
128	    }
129	    return Postprocess(entity);
130	  }
131	  return ge::SUCCESS;
132	}
133	
134	ge::Status SendState::Postprocess(CommEntity &entity) {
135	  entity.SetDataTransferJob(nullptr);
136	  return entity.ChangeState(FsmState::FSM_IDLE_STATE);
137	}
138	
139	ge::Status SendState::QueryCacheEntryAndOffset(CommEntity &entity, CacheEntry &cache_entry, uint64_t &offset) {
140	  const TransferCacheReq &request = entity.GetRequest();
141	  auto &recv_statistic_info = entity.GetRecvStatisticInfo();
142	  recv_statistic_info.req_info_get_times++;
143	  ge::Status ret = ge::SUCCESS;
144	  const auto cache_manager = entity.GetCacheManager();
145	  LLM_CHECK_NOTNULL(cache_manager, "entity:%s get cache manager failed", entity.GetDesc().c_str());
146	  entity.SetCacheKeyToRemove({UINT64_MAX, UINT64_MAX});
147	  if (request.is_pull_block == 1U) {
148	    offset = 0U;
149	    return QueryBlocksCache(*cache_manager, request, cache_entry);
150	  }
151	
152	  DataCacheKey data_cache_key;
153	  bool is_prefix = false;
154	  if (!GetCacheKey(*cache_manager, request, data_cache_key, is_prefix)) {
155	    ret = QueryCacheByCacheId(*cache_manager, request, cache_entry);
156	    LLM_CHK_STATUS_RET(ret, "query cache by cache id[%lu] failed", request.cache_id);
157	    LLM_CHK_BOOL_RET_STATUS(request.batch_index < cache_entry.batch_size, ge::LLM_KV_CACHE_NOT_EXIST,
158	                            "batch_index (%lu)out of range [0, %u)", request.batch_index, cache_entry.batch_size);
159	    offset = request.batch_index * cache_entry.stride;
160	    return ge::SUCCESS;
161	  }
162	  // query by cache_key
163	  LLM_CHK_BOOL_RET_STATUS(cache_manager->GetCacheEntry(data_cache_key, is_prefix, cache_entry),
164	                          ge::LLM_KV_CACHE_NOT_EXIST,
165	                          "Failed to get cache entry by data_cache_key: (%lu, %lu), is_prefix = %d",
166	                          data_cache_key.first, data_cache_key.second, static_cast<int32_t>(is_prefix));
167	  offset = cache_entry.id_to_batch_index_and_size.at(data_cache_key.first).first * cache_entry.stride;
168	  if ((!is_prefix) && (cache_entry.is_owned) && (request.is_pull_block == 0U)) {
169	    LLMLOGI("CacheKey(%lu, %lu) need to be removed after pulling", data_cache_key.first, data_cache_key.second);
170	    entity.SetCacheKeyToRemove(data_cache_key);
171	  }
172	  return ge::SUCCESS;
173	}
174	
175	ge::Status SendState::QueryBlocksCache(const CacheManager &cache_manager, const TransferCacheReq &request,
176	                                       CacheEntry &cache_entry) {
177	  std::pair<uint64_t, uint64_t> cache_key = std::make_pair(request.req_id, request.model_id);
178	  LLM_CHK_BOOL_RET_STATUS(cache_manager.GetCacheEntry(cache_key, false, cache_entry), ge::LLM_KV_CACHE_NOT_EXIST,
179	                          "cache_id:%ld, req:%lu, model_id:%lu, cache not found", request.cache_id, request.req_id,
180	                          request.model_id);
181	  LLM_CHK_BOOL_RET_STATUS(request.block_size != 0U, ge::LLM_PARAM_INVALID,
182	                          "req:%lu, model_id:%lu, block size(%lu) is invalid", request.req_id, request.model_id,
183	                          request.block_size);
184	  return ge::SUCCESS;
185	}
186	
187	bool SendState::GetCacheKey(const CacheManager &cache_manager, const TransferCacheReq &request,
188	                            std::pair<uint64_t, uint64_t> &cache_key, bool &is_prefix) {
189	  bool found = true;
190	  if (request.cache_id >= 0) {
191	    const auto search_key = std::make_pair(request.cache_id, request.batch_index);
192	    found = cache_manager.GetCacheKey(search_key, cache_key);
193	    if (found) {
194	      LLMLOGI("cache_id:%lu, batch_index:%lu maps to CacheKey(req_id:%lu, model_id:%lu)", search_key.first,
195	              search_key.second, cache_key.first, cache_key.second);
196	    } else {
197	      LLMLOGI("cache_id:%lu, batch_index:%lu maps to No CacheKey", search_key.first, search_key.second);
198	    }
199	  } else {
200	    is_prefix = request.prefix_id != UINT64_MAX;
201	    auto real_req_id = is_prefix ? request.prefix_id : request.req_id;
202	    cache_key = std::make_pair(real_req_id, request.model_id);
203	  }
204	  return found;
205	}
206	
207	int32_t SendState::ResolveTransferType(const TransferCacheReq &request, const CacheEntry &cache_entry) {
208	  auto dst_placement = static_cast<CachePlacement>(request.dst_placement);
209	  auto src_placement = cache_entry.placement;
210	  if (src_placement == CachePlacement::DEVICE && dst_placement == CachePlacement::DEVICE) {
211	    return kTransferTypeD2D;
212	  }
213	  if (src_placement == CachePlacement::DEVICE && dst_placement == CachePlacement::HOST) {
214	    return kTransferTypeD2H;
215	  }
216	  if (src_placement == CachePlacement::HOST && dst_placement == CachePlacement::DEVICE) {
217	    return kTransferTypeH2D;
218	  }
219	  return -1;
220	}
221	
222	ge::Status SendState::QueryCacheByCacheId(const CacheManager &cache_manager, const TransferCacheReq &request,
223	                                          CacheEntry &cache_entry) {
224	  LLM_CHK_BOOL_RET_STATUS(cache_manager.GetCacheEntry(request.cache_id, cache_entry), ge::LLM_KV_CACHE_NOT_EXIST,
225	                          "cache_id:%ld, cache not found", request.cache_id);
226	  LLM_CHK_BOOL_RET_STATUS(request.batch_index < static_cast<uint64_t>(cache_entry.batch_size),
227	                          ge::LLM_KV_CACHE_NOT_EXIST, "cache id:%ld, batch_index (%lu) >= batch_size (%u)",
228	                          request.cache_id, request.batch_index, cache_entry.batch_size);
229	  return ge::SUCCESS;
230	}
231	
232	ge::Status SendState::CheckParam(const CacheEntry &cache_entry, const TransferCacheReq &request) {
233	  size_t cache_num = (request.src_tensor_indices_size != 0U) ? static_cast<size_t>(request.src_tensor_indices_size)
234	                                                             : cache_entry.cache_addrs.size();
235	  LLM_CHK_BOOL_RET_STATUS(cache_num == request.num_tensors, ge::LLM_PARAM_INVALID,
236	                          "num_tensors mismatches, src = %zu, dst = %u", cache_num, request.num_tensors);
237	  LLM_CHK_BOOL_RET_STATUS((request.is_pull_block == 0U) == (cache_entry.num_blocks == 0), ge::LLM_PARAM_INVALID,
238	                          "request pull block = %u, but local cache is block = %d", request.is_pull_block,
239	                          (cache_entry.num_blocks == 0) ? 0 : 1);
240	  if (request.is_pull_block == 1U) {
241	    // local is PA
242	    LLM_CHK_BOOL_RET_STATUS((request.max_block_index == 0) || (request.max_block_index < cache_entry.num_blocks),
243	                            ge::LLM_PARAM_INVALID,
244	                            "request max_block_index out of bound, requested = %lu, local block_num = %lu",
245	                            request.max_block_index, cache_entry.num_blocks);
246	  } else {
247	    // local is Non-PA
248	    if (request.block_size > 0U) {
249	      if (request.dst_placement == static_cast<int32_t>(CachePlacement::HOST)) {
250	        // is d2h c2b
251	        auto padded_size = (cache_entry.stride + request.block_size - 1U) / request.block_size * request.block_size;
252	        LLM_CHK_BOOL_RET_STATUS(request.pull_size <= padded_size, ge::LLM_PARAM_INVALID,
253	                                "pull_size(%lu) > padded_cache_stride(%lu), block_size = %lu, cache_stride = %lu",
254	                                request.pull_size, padded_size, request.block_size, cache_entry.stride);
255	      }
256	    } else {
257	      LLM_CHK_BOOL_RET_STATUS(request.pull_size <= cache_entry.stride, ge::LLM_PARAM_INVALID,
258	                              "pull_size(%lu) > cache stride(%lu)", request.pull_size, cache_entry.stride);
259	    }
260	  }
261	  if (request.src_tensor_indices_size != 0U) {
262	    LLM_CHK_BOOL_RET_STATUS(
263	        (cache_num <= cache_entry.cache_addrs.size()) &&
264	            (static_cast<size_t>(request.src_tensor_start_index) < cache_entry.cache_addrs.size()) &&
265	            (static_cast<size_t>(request.src_tensor_start_index + request.src_tensor_indices_size - 1) <
266	             cache_entry.cache_addrs.size()),
267	        ge::LLM_PARAM_INVALID,
268	        "src_tensor_indices_size[%u] or src_tensor_start_index[%u] is invalid, src_cache num is[%zu]",
269	        request.src_tensor_indices_size, request.src_tensor_start_index, cache_entry.cache_addrs.size());
270	  } else {
271	    LLM_CHK_BOOL_RET_STATUS(static_cast<size_t>(request.src_tensor_start_index) < cache_entry.cache_addrs.size(),
272	                            ge::LLM_PARAM_INVALID,
273	                            "src_tensor_start_index[%u] is out of range, cache_addrs size is[%zu]",
274	                            request.src_tensor_start_index, cache_entry.cache_addrs.size());
275	  }
276	  return ge::SUCCESS;
277	}
278	
279	std::unordered_set<uint64_t> SendState::GetLayerRangeTensorIndices(const TransferCacheReq &request) {
280	  if (request.src_tensor_indices_size == 0U) {
281	    return {};
282	  }
283	  std::unordered_set<uint64_t> tensor_indices;
284	  const size_t layer_start_tensor_index = static_cast<size_t>(request.src_tensor_start_index);
285	  const size_t layer_range_num_tensors = static_cast<size_t>(request.src_tensor_indices_size);
286	  for (uint64_t i = layer_start_tensor_index; i < layer_start_tensor_index + layer_range_num_tensors; ++i) {
287	    tensor_indices.insert(i);
288	  }
289	  return tensor_indices;
290	}
291	}  // namespace llm
