67	  auto ret = llm_datadist.SetRole(role, options);
68	  if (ret != LLM_SUCCESS) {
69	    printf("[ERROR] SetRole failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
70	    return -1;
71	  }
72	  printf("[INFO] SetRole success\n");
73	  return 0;
74	}
