213	int32_t RunDecoderSample(const char *device_id, const char *local_ip, const char *remote_ip) {
214	  printf("[INFO] Decoder Sample start\n");
215	  // 1. 初始化
216	  LlmDataDist llm_datadist(kDecoderClusterId, LlmRole::kDecoder);
217	  if (Initialize(llm_datadist, device_id) != 0) {
218	    return -1;
