226	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
227	    return -1;
228	  }
229	
230	  // 3. 等待prompt写完cache，实际业务场景可通过合适方式实现通知
231	  std::this_thread::sleep_for(std::chrono::seconds(kWaitPromptInitTime));
232	
233	  // 4. 与prompt建链
234	  if (Link(llm_datadist, local_ip, remote_ip) != 0) {
235	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
236	    return -1;
237	  }
238	  linked = true;
239	
240	  // 5. 从prompt拉取cache
241	  if (PullCache(llm_datadist, cache_id) != 0) {
242	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
243	    return -1;
244	  }
245	
246	  if (CheckBuffers(buffers, {0, 1, 2, 3}) != 0) {
