266	
267	  if (CheckBuffers(buffers, {4, 5, 6, 7}) != 0) {
268	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
269	    return -1;
270	  }
271	
272	  // 9. 释放cache与llmDataDist
273	  llm_datadist.Finalize();
274	  printf("[INFO] Finalize success\n");
275	  printf("[INFO] Decoder Sample end\n");
276	  return 0;
